mapper.select:
SELECT COUNT(1)
FROM room r
JOIN room_category rc ON rc.room_category_id = r.room_category_id
    AND rc.camp_id = r.camp_id
    AND rc.status = 1
    AND rc.is_deleted = 0
WHERE r.camp_id = #{campId}
  AND r.poi_id = #{poiId}
  AND r.room_category_id = #{roomCategoryId}
  AND r.room_id = #{roomId}
  AND r.status = 1
  AND r.is_deleted = 0
  AND (r.lock_status IS NULL OR r.lock_status != 'offline')

SELECT COUNT(1)
FROM order_main om
WHERE om.camp_id = #{campId}
  AND om.room_id = #{roomId}
  AND om.status IN ('booked', 'checked_in')
  AND om.is_deleted = 0
  AND om.start_at < #{endAt}
  AND om.end_at > #{startAt}

  AND om.order_id != #{excludeOrderId}

SELECT COUNT(1)
FROM room_status_block rsb
WHERE rsb.camp_id = #{campId}
  AND rsb.room_id = #{roomId}
  AND rsb.status = 'closed'
  AND rsb.is_deleted = 0
  AND rsb.biz_date >= #{blockStartDate}
  AND rsb.biz_date <= #{blockEndDate}

mapper.update:
UPDATE room
SET clean_status = #{cleanStatus},
    updated_at = NOW()
WHERE camp_id = #{campId}
  AND room_id = #{roomId}
  AND is_deleted = 0

mapper.select:
SELECT COUNT(1)
FROM clean_task
WHERE camp_id = #{campId}
  AND room_id = #{roomId}
  AND task_type = 'checkout_clean'
  AND task_status IN ('pending', 'processing')

SELECT COUNT(1)
FROM order_guest
WHERE order_id = #{orderId}
